<div class="field"><label for="current_password">Aktuelles Passwort</label><input type="password" id="current_password" name="current_password" required autocomplete="current-password"></div>
<div class="field"><label for="new_password">Neues Passwort (mind. 12 Zeichen)</label><input type="password" id="new_password" name="new_password" required minlength="12" autocomplete="new-password"></div>
<div class="field"><label for="new_password2">Neues Passwort wiederholen</label><input type="password" id="new_password2" name="new_password2" required minlength="12" autocomplete="new-password"></div>
